-- Departamentos y puestos del cruce (por número de empleado).
-- Se aplica DESPUÉS del parche de usuarios. No toca nada más.
\set ON_ERROR_STOP on
BEGIN;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM (VALUES ('A&B'),('ALMACEN'),('BODAS'),('CABALLERIZAS'),('CONTABILIDAD'),('DIRECCION'),('HOTEL'),('MANTENIMIENTO'),('OPERACIONES'),('RECEPCION'),('RECURSOS HUMANOS'),('RESERVACIONES'),('SISTEMAS'),('SPA')) v(n) WHERE NOT EXISTS (SELECT 1 FROM departments d WHERE d.name = v.n)) THEN
    RAISE EXCEPTION 'Falta algún departamento en el catálogo; revisar antes de aplicar.';
  END IF;
END $$;

DO $$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM users WHERE "employeeNumber" IN ('020804','020886','020918','020836','020685','020579','020712','020742','020700','020707','020603','020612','060843','060840','060789','060794','00130753','00130762','00130756','060918','060883','00130755','060717','00130765','060917','060661','060872','060912','060849','060766','060880','060921','060913','060925','00130752','060862','060922','040897','040726','040010','040013','030014','00130749','030822','030015','030635','030834','030008','030664','030003','030900','030787','030009','110875','030908','030144','030838','030808','030760','030019','030762','030899','030020','030892','030752','030675','030007','030002','030010','030895','030802','030011','030865','030738','030248','030678','030025','030017','030016','030004','030901','040831','020401','110706','110088','110002','110890','060923','00130757','060887','00130759','060879','060891','00130758','060780','080001','080588','080570','080789','080559','040905','040914','040009','090659','040807','040569','040012','040767','040876','040759','040898','040001','040858','040732','040003','040873','030018','040014','040006','010911','010001','010872','010792','010657','010722','010851','0010002','0010005','010888','070903','0010004','070696','070705','070359','070701','070646','070699','070562','050004','050003','050884','050002','050005','050006','050745','050924','050857','050909','030844','040784','040848','040011');
  IF n <> 152 THEN RAISE EXCEPTION 'Se esperaban 152 cuentas del cruce y hay %', n; END IF;
END $$;

